/// <summary>
/// /// METInventInventoryDataServiceDiagnosticToolActivities
/// </summary>
internal final class METInventInventoryDataServiceDiagnosticToolActivities
{
    private const str ActivityNamePrefix = 'InventoryVisibility.DiagnosticTool.';
    private METInventInstrumentationLogger logger;

}

Method.Source:
/// <summary>
/// /// Initializes a new instance of the METInventInventoryDataServiceDiagnosticToolActivities class.
/// </summary>
/// <param name = "_logger">METInventInstrumentationLogger</param>
private void new(METInventInstrumentationLogger _logger)
{
    logger = _logger;
}

/// <summary>
/// /// Creates a new instance of the METInventInventoryDataServiceDiagnosticToolActivities class from a logger.
/// </summary>
/// <param name = "_logger">METInventInstrumentationLogger</param>
/// <returns>METInventInventoryDataServiceDiagnosticToolActivities</returns>
public static METInventInventoryDataServiceDiagnosticToolActivities newFromLogger(METInventInstrumentationLogger _logger)
{
    return new METInventInventoryDataServiceDiagnosticToolActivities(_logger);
}

/// <summary>
/// /// Gets the activity context for running the on-hand diagnostic.
/// </summary>
/// <param name = "_onlyCheckPreviousMismatchedData">boolean</param>
/// <param name = "_onlyCheckOpenItems">boolean</param>
/// <param name = "_onlyCheckWHSItems">boolean</param>
/// <param name = "_fixData">boolean</param>
/// <param name = "_companies">container</param>
/// <param name = "_items">container</param>
/// <param name = "_locations">container</param>
/// <returns>SysInstrumentationActivityContext</returns>
public SysInstrumentationActivityContext getActivityContext_RunOnHandDiagnostic(boolean _onlyCheckPreviousMismatchedData, boolean _onlyCheckOpenItems, boolean _onlyCheckWHSItems, boolean _fixData, container _companies, container _items, container _locations)
{
    SysInstrumentationActivity activity = logger.activity(ActivityNamePrefix + 'RunOnHandDiagnostic');
    activity.addCustomProperty('companies', con2Str(_companies));
    activity.addCustomProperty('items', con2Str(_items));
    activity.addCustomProperty('locations', con2Str(_locations));

    activity.addCustomProperty('OnlyCheckPreviousMismatchedData', any2Str(_onlyCheckPreviousMismatchedData));
    activity.addCustomProperty('OnlyCheckWHSItems', any2Str(_onlyCheckWHSItems));
    activity.addCustomProperty('FixData', any2Str(_fixData));
    return logger.activityContext(activity);
}

/// <summary>
/// /// Gets the activity context for running the on-hand diagnostic per company.
