public SysInstrumentationActivityContext getActivityContext_RunOnHandDiagnosticPerCompany(DataAreaId _dataAreaId)
{
    SysInstrumentationActivity activity = logger.activity(ActivityNamePrefix + 'RunOnHandDiagnostic');
