}

/// <summary>
/// /// Gets the activity context for the initial process status.
/// </summary>
/// <param name = "_companies">container</param>
/// <returns>SysInstrumentationActivityContext</returns>
public SysInstrumentationActivityContext getActivityContext_InitialProcessStatus(container _companies)
{
    SysInstrumentationActivity activity = logger.activity(ActivityNamePrefix + 'InitialProcessStatus');
    var conpaniesInfo = con2Str(_companies);
    activity.addCustomProperty('Inital companies', conpaniesInfo);

    return logger.activityContext(activity);
}

