/// <summary>
/// /// Gets the activity context for running the on-hand diagnostic per batch.
/// </summary>
/// <param name = "_batchNo">int</param>
/// <param name = "_checkCount">int</param>
/// <returns>SysInstrumentationActivityContext</returns>
public SysInstrumentationActivityContext getActivityContext_RunOnHandDiagnosticPerBatch(int _batchNo, int _checkCount)
{
    SysInstrumentationActivity activity = logger.activity(ActivityNamePrefix + 'RunOnHandDiagnosticPerBatch');

    activity.addCustomProperty('BatchNo', int642Str(_batchNo));
    activity.addCustomProperty('CheckCount', any2Str(_checkCount));

    return logger.activityContext(activity);
}

