/// <summary>
/// /// Logs diagnostic information for on-hand items per batch.
/// </summary>
/// <param name = "_activityContext">SysInstrumentationActivityContext</param>
/// <param name = "_batchNo">int</param>
/// <param name = "_startTime">utcdatetime</param>
/// <param name = "_endTime">utcdatetime</param>
/// <param name = "_beforeCount">int</param>
/// <param name = "_afterCount">int</param>
public void logOnHandDiagnosticPerBatchInfo(
    SysInstrumentationActivityContext   _activityContext,
    int                                 _batchNo,
    utcdatetime                         _startTime,
    utcdatetime                         _endTime,
    int                                 _beforeCount,
    int                                 _afterCount)
{
    _activityContext.addCustomProperty('BatchNo', int642Str(_batchNo));
    _activityContext.addCustomProperty('StartTime', datetime2Str(_startTime));
    _activityContext.addCustomProperty('EndTime', datetime2Str(_endTime));
    _activityContext.addCustomProperty('BeforeCount', int642Str(_beforeCount));
    _activityContext.addCustomProperty('AfterCount', int642Str(_afterCount));
}

